npm install -D @testcontainers/mongodb mongodb
// test/setup.ts
import { MongoDBContainer, StartedMongoDBContainer } from '@testcontainers/mongodb';
import { MongoClient } from 'mongodb';
export let mongoContainer: StartedMongoDBContainer;
export let mongoClient: MongoClient;
export async function setupMongo() {
mongoContainer = await new MongoDBContainer('mongo:8').start();
mongoClient = new MongoClient(mongoContainer.getConnectionString(), { directConnection: true });
await mongoClient.connect();
}
export async function teardownMongo() {
await mongoClient?.close();
await mongoContainer?.stop();
}
