In tests:
import { MongoClient } from 'mongodb';
let client: MongoClient;
let db;
beforeAll(async () => {
client = new MongoClient(process.env.TEST_MONGO_URI!);
await client.connect();
db = client.db('test');
});
afterAll(async () => { await client.close(); });
afterEach(async () => {
// drop all collections between tests
const cs = await db.collections();
await Promise.all(cs.map(c => c.deleteMany({})));
});
test('insert + find', async () => {
await db.collection('users').insertOne({ name: 'Ada' });
expect(await db.collection('users').findOne({ name: 'Ada' })).toBeDefined();
});

